#include <bits/stdc++.h>

using namespace std;

int main() {
    // your code goes here
    int t;
    cin>>t;
    
    while(t--){
        int n;
        cin>>n;
        int m=3*n;
        vector<long long> a(m), p(m+1);
        for(auto &x:a) cin>>x;
        
        sort(a.rbegin(), a.rend());
        for(int i=0; i<m;i++)
        p[i+1]=p[i]+a[i];
        
        long long ans=0;
        for(int A=0; A<=n; A++)
            {
                int mx=n-A;
                
                auto d= [&](int B){
                    return a[A+2*B] + a[A+2*B+1] - 3LL*a[3*n -2*A-B-1];
                    
                };
                int l=0, r=mx;
                while(l<r){
                    int md=(l+r)/2;
                    
                    if(d(md)>=0)
                    l=md+1;
                    else
                    r=md;
                }
                for(int B:{max(0, l-1),l}){
                    if(B>mx ) continue;
                    
                    long long cur= 2LL*p[A]+p[A+2*B]+ 3LL*p[3*n-2*A-B];
                    ans=max(ans, cur);
                }
            }
            cout<<ans<<endl;
    }
}
